gagK(){return"\u041f\u0440\u0438\u043c\u0435\u0440\u043d\u0438 \u0434\u0430\u043d\u043d\u0438 \u043d\u0430 \u0441\u044a\u0440\u0432\u044a\u0440\u0430 \u043d\u0430 \u0434\u0435\u043c\u043e\u0442\u043e: \u0432\u0438\u0436\u0434\u0430\u0442 \u0433\u0438 \u0432\u0441\u0438\u0447\u043a\u0438 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430, \u0432\u043b\u0435\u0437\u043b\u0438 \u0432 \u043d\u0435\u0433\u043e."},
gafM(){return"\u041f\u0438\u0448\u0435\u0448 \u043a\u0430\u0442\u043e \u0434\u043e\u043c\u0430\u043a\u0438\u043d. \u0412\u043e\u0434\u0430\u0447\u044a\u0442 \u0433\u043e \u0432\u0438\u0436\u0434\u0430 \u0432\u0435\u0434\u043d\u0430\u0433\u0430 \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u0442\u043e \u0441\u0438."},
gafU(){return"\u041f\u0440\u0438\u043c\u0435\u0440\u0435\u043d \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440: \u0434\u043e\u043c\u0430\u043a\u0438\u043d\u044a\u0442 \u043f\u0438\u0448\u0435 \u043e\u0442 Stavia Business."},
gaiW(){return"\u041f\u0440\u043e\u0447\u0435\u0442\u0435\u043d\u043e \u0441\u0430\u043c\u043e \u043e\u0442 \u043a\u043e\u0434\u0430: \u0442\u0430\u0437\u0438 \u0440\u0435\u0437\u0435\u0440\u0432\u0430\u0446\u0438\u044f \u044f \u043d\u044f\u043c\u0430 \u043d\u0430 \u0441\u044a\u0440\u0432\u044a\u0440\u0430 \u043d\u0430 \u0434\u0435\u043c\u043e\u0442\u043e. \u041f\u0440\u0438\u043c\u0435\u0440\u0435\u043d \u043a\u043e\u0434, \u0431\u0435\u0437 \u043f\u043e\u0434\u043f\u0438\u0441."},
