gasR(){return"\u041f\u0440\u043e\u0432\u0435\u0440\u0438 \u0432\u0440\u044a\u0437\u043a\u0430\u0442\u0430. \u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u0442\u043e \u043f\u043e\u043a\u0430\u0437\u0432\u0430 \u0442\u043e\u0432\u0430, \u043a\u043e\u0435\u0442\u043e \u0435 \u043d\u0430 \u0441\u044a\u0440\u0432\u044a\u0440\u0430."},
gaiU(){return"\u0422\u043e\u0437\u0438 \u043a\u043e\u0434 \u043d\u0435 \u0435 \u0438\u0437\u0434\u0430\u0434\u0435\u043d \u043e\u0442 Stavia \u0438\u043b\u0438 \u0435 \u043f\u0440\u043e\u043c\u0435\u043d\u0435\u043d. \u041d\u0435 \u043f\u0443\u0441\u043a\u0430\u0439 \u043a\u043e\u043b\u0430\u0442\u0430."},
gaiQ(){return"\u0422\u043e\u0437\u0438 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u043e\u0449\u0435 \u043d\u0435 \u043c\u043e\u0436\u0435 \u0434\u0430 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0432\u0430 \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043d\u0438 \u043a\u043e\u0434\u043e\u0432\u0435: \u0441\u0432\u044a\u0440\u0436\u0438 \u0433\u043e \u0441 \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442 \u0437\u0430 \u043c\u0430\u043b\u043a\u043e \u0438 \u0441\u043a\u0430\u043d\u0438\u0440\u0430\u0439 \u043f\u0430\u043a."},
gajl(){return"\u041a\u043e\u0434\u044a\u0442 \u043d\u0435 \u0435 \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043d. \u041f\u043e\u043c\u043e\u043b\u0438 \u0432\u043e\u0434\u0430\u0447\u0430 \u0434\u0430 \u043e\u0442\u0432\u043e\u0440\u0438 \u043a\u043e\u0434\u0430 \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u0442\u043e \u0441 \u0432\u043a\u043b\u044e\u0447\u0435\u043d \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442."},
gat5(){return"\u0422\u0432\u044a\u0440\u0434\u0435 \u043c\u043d\u043e\u0433\u043e \u0440\u0435\u0437\u0435\u0440\u0432\u0430\u0446\u0438\u0438"},
gat2(){return"\u0417\u0430 \u0437\u0430\u0449\u0438\u0442\u0430 \u043e\u0442 \u0437\u043b\u043e\u0443\u043f\u043e\u0442\u0440\u0435\u0431\u0438 \u0435\u0434\u0438\u043d \u0432\u043e\u0434\u0430\u0447 \u043c\u043e\u0436\u0435 \u0434\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u0438 \u0434\u043e 30 \u0440\u0435\u0437\u0435\u0440\u0432\u0430\u0446\u0438\u0438 \u043d\u0430 \u0447\u0430\u0441."},
gat8(){return"\u0421\u044a\u043e\u0431\u0449\u0435\u043d\u0438\u0435\u0442\u043e \u043d\u0435 \u0435 \u0438\u0437\u043f\u0440\u0430\u0442\u0435\u043d\u043e"},
gTU(){return"\u0417\u0430 \u0442\u0432\u043e\u044f \u0441\u0438\u0433\u0443\u0440\u043d\u043e\u0441\u0442 \u0432 \u0447\u0430\u0442\u0430 \u043d\u0435 \u0441\u0435 \u0438\u0437\u043f\u0440\u0430\u0449\u0430\u0442 \u043b\u0438\u043d\u043a\u043e\u0432\u0435, \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0438, \u043d\u043e\u043c\u0435\u0440\u0430 \u043d\u0430 \u043a\u0430\u0440\u0442\u0438 \u0438\u043b\u0438 \u0441\u043c\u0435\u0442\u043a\u0438 \u0438 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0437\u0430 \u043f\u043b\u0430\u0449\u0430\u043d\u0435. Stavia \u043d\u0438\u043a\u043e\u0433\u0430 \u043d\u0435 \u0438\u0441\u043a\u0430 \u043f\u043b\u0430\u0449\u0430\u043d\u0435 \u0438\u0437\u0432\u044a\u043d \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u0442\u043e."},
